let currentBookKey="hanngu1", V=[], G=[], Q=[], EX={};
let answered=0,correct=0,currentWord=null;

function setBook(key){
  currentBookKey=key;
  const book=DATA.books[key];
  V=book.lessons?Object.values(book.lessons).flatMap(l=>l.vocab):[];
  G=book.lessons?Object.values(book.lessons).flatMap(l=>l.grammar):[];
  Q=book.lessons?Object.values(book.lessons).flatMap(l=>l.questions):[];
  EX=key==="hanngu1"?(DATA.examples_hanngu1||{}):(key==="hanngu2"?(DATA.examples_hanngu2||DATA.examples||{}):(DATA.examples_hanngu3||{}));
  document.getElementById("bookSub").textContent=book.description||"";
  document.getElementById("vcount").textContent=V.length;
  document.getElementById("lcount").textContent=Object.keys(book.lessons||{}).length;
  document.getElementById("gcount").textContent=G.length;
  document.getElementById("qcount").textContent=Q.length;
  document.getElementById("grammarTitle").textContent="📘 NGỮ PHÁP – "+book.name.toUpperCase();
  document.getElementById("quizTitle").textContent="🎯 LUYỆN TẬP – "+book.name.toUpperCase();
  lesson.innerHTML='<option value="all">Tất cả bài</option>';
  Object.values(book.lessons||{}).forEach(l=>{
    const o=document.createElement("option");
    o.value=l.name.replace("Bài ",""); o.textContent=l.name; lesson.appendChild(o);
  });
  lesson.value="all";
  renderVocab(); renderGrammar(); renderQuiz();
}
function esc(s){return String(s).replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#039;"}[m]));}
function getChineseVoice(){
  const vs=speechSynthesis.getVoices();
  const zh=vs.filter(v=>/^(zh-CN|zh-Hans|cmn)/i.test(v.lang||""));
  return zh.find(v=>/中国|Chinese|Mandarin|普通话|Mainland/i.test(v.name||""))
      ||zh[0]
      ||vs.find(v=>/^zh(-|_|$)/i.test(v.lang||""))
      ||null;
}
function speak(t){
  try{
    speechSynthesis.cancel();
    const u=new SpeechSynthesisUtterance(String(t));
    u.lang="zh-CN";
    u.rate=.82;
    const v=getChineseVoice();
    if(v)u.voice=v;
    speechSynthesis.speak(u);
  }catch(e){}
}
speechSynthesis.onvoiceschanged=()=>getChineseVoice();
function speakWord(x){
  const lesson=x[0], word=x[1], py=x[2];
  const context={
    "25|得|de":"他跑得很快。",
    "27|得|dé":"他得到了第一名。",
    "19|长|cháng":"这条路很长。",
    "20|过|guò":"我去过北京。",
    "19|了|le":"我吃饭了。",
    "24|了|le":"他已经到了。",
    "27|了|le":"下雨了。"
  };
  speak(context[lesson+"|"+word+"|"+py]||word);
}
function renderVocab(){
  let l=lesson.value,a=V.filter(x=>l==="all"||x[0]===l),last="",o="";
  a.forEach((x,idx)=>{
    if(x[0]!==last){o+=`<div class="lessonTitle">📚 BÀI ${x[0]}</div>`;last=x[0]}
    let ex=EX[x[1]];
    const aid=`analysis_${String(x[0])}_${idx}`;
    o+=`<article class="vocab-card" data-word="${esc(x[1])}" data-analysis-id="${aid}"><div class="vtop"><div><div class="hanzi">${esc(x[1])}</div><div class="py">${esc(x[2])}</div><div class="meaning">${esc(x[3])}</div></div><span class="badge">Bài ${x[0]}</span></div>
    <div class="actions"><button onclick='speakWord(${JSON.stringify(x)})'>🔊 Phát âm</button><button onclick='openWriter(${JSON.stringify(x)})'>✍️ Viết chữ</button></div>
    <div class="vocab-analysis" id="${aid}"><button class="vocab-analysis-toggle" type="button" onclick="toggleVocabAnalysis(this)">🧩 Bộ thủ · Chiết tự · 🧠 Mẹo nhớ chữ Hán</button><div class="vocab-analysis-body"><div class="analysis-loading">Đang chuẩn bị dữ liệu bộ thủ và chiết tự…</div></div></div>
    ${ex?`<div class="example"><b>${esc(ex[0])}</b><div class="p">${esc(ex[1])}</div><div class="vi">${esc(ex[2])}</div><div class="actions"><button onclick='speak(${JSON.stringify(ex[0])})'>🔊 Đọc câu</button></div></div>`:""}</article>`;
  });
  vocabList.innerHTML=o;
  hydrateVocabAnalysis();
}
function toggleVocabAnalysis(btn){
  const box=btn.closest('.vocab-analysis');
  if(!box)return;
  box.classList.toggle('open');
  if(box.classList.contains('open') && !box.dataset.ready) hydrateOneVocabAnalysis(box);
}
function hydrateOneVocabAnalysis(box){
  if(!box || box.dataset.ready)return;
  const card=box.closest('.vocab-card');
  const word=card?.dataset.word||'';
  const rows=V.filter(x=>x[1]===word);
  const row=rows[0];
  const body=box.querySelector('.vocab-analysis-body');
  if(!row||!body)return;
  const html=[...word].filter(c=>/^[\u3400-\u9fff]$/.test(c)).map(c=>renderWordCharAnalysis(c,row[3])).join('');
  const radicalSummary=[...word].filter(c=>/^[\u3400-\u9fff]$/.test(c)).map(c=>{
    const r=getPrimaryRadical(c);
    return r?`<span class="radicalSummaryChar">${esc(c)} → ${formatRadicalInline(r)}</span>`:`<span class="radicalSummaryChar">${esc(c)} → chưa xác định</span>`;
  }).join(' <span class="radicalSep">＋</span> ');
  body.innerHTML=(radicalSummary?`<div class="radicalSummary"><b>🔹 Bộ thủ theo từng chữ:</b> ${radicalSummary}</div>`:'')+html+`<div class="char-analysis-note">💡 <b>Lưu ý:</b> Một từ có thể có nhiều bộ thủ vì mỗi chữ có một bộ thủ riêng. Không lấy các thành phần nằm sâu bên trong chiết tự làm bộ thủ của chữ.</div>`;
  box.dataset.ready='1';
}
function hydrateVocabAnalysis(){
  loadRadicalData().then(()=>{
    document.querySelectorAll('.vocab-analysis.open').forEach(box=>{
      delete box.dataset.ready;
      hydrateOneVocabAnalysis(box);
    });
  });
}
function getPrimaryRadical(char){
  const info=RADICAL_DATA[char]||{};
  if(info && typeof info.radical === "string" && info.radical.trim()) return info.radical.trim();
  return RADICAL_FALLBACK[char]||"";
}

function renderWordCharAnalysis(char,wordMeaning){
  const info=getStaticCharInfo(char,RADICAL_DATA[char]||{});
  // Bộ thủ được lấy THEO TỪNG CHỮ trong từ.
  // Có thể có nhiều bộ thủ trong một TỪ (mỗi chữ một bộ thủ),
  // nhưng KHÔNG gom tất cả thành phần lồng nhau của một chữ thành bộ thủ.
  const radical = getPrimaryRadical(char);
  const radicals = radical ? [radical] : [];
  const tree=parseDecomposition(info.decomposition||'');
  const structure=tree?.op?componentStructureLabel(tree.op):'';
  const comps=tree?collectTreeChars(tree,[]).filter(c=>c!==char):[];
  const uniq=[...new Set(comps)];
  const compText=uniq.length?uniq.map(c=>{
    const m=COMPONENT_VI[c]||EXTRA_COMPONENT_VI[c]||RADICAL_MEANINGS[c]||RADICAL_NAMES[c]||'thành phần';
    const p=COMPONENT_PINYIN[c]||'';
    return `<span class="componentChar">${esc(c)}</span>${p?` <span class="componentName">${esc(p)}</span>`:''} — ${esc(m)}`;
  }).join(' ＋ '):'Chưa có phân rã chi tiết trong dữ liệu đang tải';
  const mn=getMnemonic(char,info,wordMeaning);
  return `<div class="char-analysis"><div class="char-analysis-head"><span class="char-analysis-char">${esc(char)}</span><span class="char-analysis-py">${esc(info.pinyin||COMPONENT_PINYIN[char]||'')}</span></div>
    <div class="char-analysis-radical">🔹 <b>Bộ thủ của chữ ${esc(char)}:</b> ${radicals.length?radicals.map(formatRadicalInline).join(' ＋ '):'chưa xác định'}</div>
    <div class="char-analysis-structure">🧩 <b>Chiết tự:</b> ${structure?esc(structure)+' · ':''}${compText}</div>
    ${mn?`<div class="char-analysis-mnemonic">🧠 <b>Mẹo nhớ:</b> ${esc(mn)}</div>`:''}</div>`;
}

function normalizeSearchText(text){
  return String(text||"").toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g,"").replace(/đ/g,"d");
}
function doSearch(){
  const q=normalizeSearchText(search.value.trim());
  if(!q){results.style.display="none";return}
  const a=V.filter(x=>[x[1],x[2],x[3]].map(normalizeSearchText).some(v=>v.includes(q))).slice(0,20);
  results.innerHTML=a.map(x=>`<button type="button" class="search-result-item" onclick='event.preventDefault();jumpToWord(${JSON.stringify(x[1])},${JSON.stringify(x[0])})'><b>${esc(x[1])}</b> <span class="result-p">${esc(x[2])}</span> <span class="result-m">${esc(x[3])}</span></button>`).join("");
  results.style.display=a.length?"block":"none";
}
function jumpToWord(ch,lessonNo){
  document.querySelectorAll(".nav button").forEach(b=>b.classList.remove("active"));
  document.querySelector('.nav button[data-sec="vocab"]')?.classList.add("active");
  document.querySelectorAll(".section").forEach(sec=>sec.classList.remove("active"));
  document.getElementById("vocab")?.classList.add("active");
  const target=String(lessonNo);
  lesson.value=[...lesson.options].some(o=>o.value===target)?target:"all";
  renderVocab(); results.style.display="none";
  requestAnimationFrame(()=>{
    const card=[...document.querySelectorAll(".vocab-card")].find(c=>c.querySelector(".hanzi")?.textContent.trim()===String(ch).trim());
    if(card){
      card.classList.add("search-found");
      card.scrollIntoView({behavior:"smooth",block:"center"});
      setTimeout(()=>card.classList.remove("search-found"),1800);
    }
  });
}
function jump(ch){
  const x=V.find(v=>v[1]===ch); if(x)jumpToWord(x[1],x[0]);
}
function formatGrammarDetail(text){
  return esc(String(text||""))
    .replace(/&lt;b&gt;/g,"<b>")
    .replace(/&lt;\/b&gt;/g,"</b>")
    .replace(/\n/g,"<br>");
}
