let RADICAL_DATA={};
const RADICAL_DATA_STATIC={};
Object.assign(RADICAL_DATA,RADICAL_DATA_STATIC);
let RADICAL_SOURCE_READY=false;
async function loadRadicalData(){
  if(RADICAL_SOURCE_READY && Object.keys(RADICAL_DATA).length) return RADICAL_DATA;
  try{
    const url="https://raw.githubusercontent.com/skishore/makemeahanzi/master/dictionary.txt";
    const res=await fetch(url,{cache:"force-cache"});
    if(!res.ok) throw new Error("HTTP "+res.status);
    const txt=await res.text();
    const need=new Set();
    // Lấy toàn bộ chữ của Hán Ngữ 1–3, không chỉ DATA.vocab cũ.
    if(Array.isArray(DATA.vocab)) DATA.vocab.forEach(row=>{ if(row&&row[1]) [...row[1]].forEach(ch=>need.add(ch)); });
    Object.values(DATA.books||{}).forEach(book=>Object.values(book.lessons||{}).forEach(lesson=>{
      (lesson.vocab||[]).forEach(row=>{ if(row&&row[1]) [...row[1]].forEach(ch=>need.add(ch)); });
    }));
    const map={};
    txt.split(/\r?\n/).forEach(line=>{
      if(!line.trim()) return;
      try{ const o=JSON.parse(line); if(o.character && need.has(o.character)) map[o.character]=o; }catch(e){}
    });
    Object.assign(RADICAL_DATA,map);
    RADICAL_SOURCE_READY=true;
  }catch(e){
    RADICAL_SOURCE_READY=false;
  }
  return RADICAL_DATA;
}

