function getMnemonic(char, obj){
  // Chỉ hiển thị mẹo nhớ khi có câu thơ/câu vè được cung cấp sẵn.
  // Không tự sinh mẹo từ bộ thủ/chiết tự hoặc câu giải thích thông thường.
  if (obj && typeof obj.mnemonic === "string" && obj.mnemonic.trim()) return obj.mnemonic.trim();
  if (HAN_MNEMONICS[char]) return HAN_MNEMONICS[char];
  return "";
}

