function parseDecomposition(ids){
  if(!ids || ids==="？")return null;
  const ops={"⿰":2,"⿱":2,"⿴":2,"⿵":2,"⿶":2,"⿷":2,"⿸":2,"⿹":2,"⿺":2,"⿻":2,"⿲":3,"⿳":3};
  let i=0;
  function parse(){
    const ch=ids[i++]; if(!ch)return null;
    if(ops[ch]){
      const children=[];
      for(let k=0;k<ops[ch];k++)children.push(parse());
      return {op:ch,children};
    }
    return {char:ch};
  }
  return parse();
}
function collectTreeChars(node,out=[]){
  if(!node)return out;
  if(node.char){out.push(node.char);return out;}
  (node.children||[]).forEach(ch=>collectTreeChars(ch,out));
  return out;
}
function collectAllRadicals(char,data){
  // Giữ lại hàm tương thích với mã cũ nhưng chỉ trả về bộ thủ chính.
  // Tuyệt đối không duyệt decomposition để tránh hiện tượng thừa bộ thủ.
  const info=data?.[char]||{};
  if(info.radical) return [info.radical];
  if(RADICAL_FALLBACK[char]) return [RADICAL_FALLBACK[char]];
  return [];
}

function componentMeaning(c,obj){
  if(COMPONENT_VI[c])return COMPONENT_VI[c];
  if(EXTRA_COMPONENT_VI[c])return EXTRA_COMPONENT_VI[c];
  if(RADICAL_MEANINGS[c])return RADICAL_MEANINGS[c];
  if(RADICAL_NAMES[c])return "bộ "+RADICAL_NAMES[c];
  const e=obj?.etymology||{};
  if(e.semantic===c)return "thành phần gợi nghĩa";
  if(e.phonetic===c)return "thành phần gợi âm";
  return "thành phần cấu tạo";
}
function componentRole(obj,c){
  const e=obj?.etymology||{};
  if(e.semantic===c)return "gợi nghĩa";
  if(e.phonetic===c)return "gợi âm";
  return "";
}
function formatRadicalInline(r){
  const n=RADICAL_NAMES[r]||"";
  const m=RADICAL_MEANINGS[r]||"";
  return `<span class="radicalPill"><span class="radicalChar">${esc(r)}</span>${n?` <span class="radicalName">(${esc(n)})</span>`:""}${m?` <span class="radicalMeaning">— ${esc(m)}</span>`:""}</span>`;
}
function componentStructureLabel(op){
  const m={"⿰":"trái + phải","⿱":"trên + dưới","⿲":"trái + giữa + phải","⿳":"trên + giữa + dưới","⿴":"bao quanh","⿵":"trên + dưới (mở đáy)","⿶":"dưới + trên (mở đỉnh)","⿷":"trái + phần trong","⿸":"trên trái + phần trong","⿹":"trên phải + phần trong","⿺":"dưới trái + phần trong","⿻":"lồng ghép"};
  return m[op]||"cấu tạo";
}
function componentInfoFor(c,obj,source){
  const src=source?.[c]||{};
  // QUAN TRỌNG: dictionary.txt dùng definition tiếng Anh.
  // Không dùng src.definition để tránh đưa tiếng Anh vào giao diện học sinh.
  const p=(Array.isArray(src.pinyin)?src.pinyin[0]:src.pinyin)||COMPONENT_PINYIN[c]||"";
  const meaning=COMPONENT_VI[c]||EXTRA_COMPONENT_VI[c]||RADICAL_MEANINGS[c]||componentMeaning(c,obj)||"thành phần cấu tạo";
  return {p,meaning,etymology:src.etymology||null};
}
function renderComponentList(chars,obj,tree,source){
  const leaves=[];
  function walk(node,depth=0){
    if(!node)return;
    if(node.char){ if(node.char!==obj?.char) leaves.push({c:node.char,depth}); return; }
    (node.children||[]).forEach(ch=>walk(ch,depth+1));
  }
  if(tree) walk(tree,0);
  else chars.forEach(c=>leaves.push({c,depth:0}));
  if(!leaves.length)return "";
  const structure=tree?.op?componentStructureLabel(tree.op):"";
  let html=structure?`<div class="componentStructure">${esc(structure)}</div>`:"";
  html+=leaves.map(({c,depth})=>{
    if(c==="？") return `<div class="componentItem" style="padding-left:${Math.min(depth,4)*18}px"><div class="componentChar">？</div><div class="componentBody"><div class="componentName">chưa xác định</div><div class="componentMeaning">Nguồn dữ liệu chưa xác định được thành phần này</div></div></div>`;
    const isHan=/[\u3400-\u9fff\uF900-\uFAFF]/.test(c);
    const info=componentInfoFor(c,obj,source);
    if(!isHan && !info.meaning)return "";
    const role=info.etymology?.semantic===c?"gợi nghĩa":(info.etymology?.phonetic===c?"gợi âm":"");
    const pad=Math.min(depth,4)*18;
    return `<div class="componentItem" style="padding-left:${pad}px"><div class="componentChar">${esc(c)}</div><div class="componentBody">${info.p?`<div class="componentName">${esc(info.p)}</div>`:""}${info.meaning?`<div class="componentMeaning">${esc(info.meaning)}${role?` · ${esc(role)}`:""}</div>`:""}</div></div>`;
  }).join("");
  return html;
}
